  function createIcons(opts) {
    var els = document.querySelectorAll('[data-lucide]');
    els.forEach(function(el) {
      var name = el.getAttribute('data-lucide');
      var paths = iconPaths[name];
      if (!paths) { console.warn('Lucide icon not found:', name); return; }
      var w = el.className && el.className.match && el.className.match(/w-(\d+(?:\.\d+)?)/);
      var h = el.className && el.className.match && el.className.match(/h-(\d+(?:\.\d+)?)/);
      var sizeMap = {'3':12,'3.5':14,'4':16,'5':20,'6':24,'8':32};
      var sw = w ? (sizeMap[w[1]] || parseInt(w[1])*4) : 16;
      var sh = h ? (sizeMap[h[1]] || parseInt(h[1])*4) : 16;
      // Fallback: read from inline style width/height (e.g. style="width:16px;height:16px;")
      if (!w && !h && el.style) {
        var styleW = el.style.width  ? parseInt(el.style.width)  : 0;
        var styleH = el.style.height ? parseInt(el.style.height) : 0;
        if (styleW) sw = styleW;
        if (styleH) sh = styleH;
      }
      var svg = document.createElementNS('http://www.w3.org/2000/svg','svg');
      svg.setAttribute('xmlns','http://www.w3.org/2000/svg');
      svg.setAttribute('width', sw);
      svg.setAttribute('height', sh);
      svg.setAttribute('viewBox','0 0 24 24');
      svg.setAttribute('fill','none');
      svg.setAttribute('stroke','currentColor');
      svg.setAttribute('stroke-width','2');
      svg.setAttribute('stroke-linecap','round');
      svg.setAttribute('stroke-linejoin','round');
      svg.innerHTML = paths;
      // Copy classes
      svg.className.baseVal = el.className.baseVal || el.className || '';
      // Copy inline style so color attributes (e.g. color:#818cf8) transfer to the SVG
      if (el.getAttribute('style')) {
        svg.setAttribute('style', el.getAttribute('style'));
      }
      el.parentNode.replaceChild(svg, el);
    });
  }
